-- Niet Café 36: ФАКТИЧЕСКИЕ ЦЕНЫ ИЗ НАКЛАДНЫХ И ЧЕКОВ (сентябрь — ноябрь 2026).
-- Supabase -> SQL Editor -> New query -> вставить всё -> Run. Можно запускать повторно.
--
-- Что делает:
--   1) Ищет ваши продукты по названию (помидоры = томаты, филе куриное = куриное филе и т. п.).
--   2) Ставит цену за вашу единицу (кг / л / шт / г / мл) по последней накладной или чеку.
--      Цена — фактически оплаченная, со скидкой. Фасовки пересчитаны: «кетчуп 5 л за 3500» → 700 ₸/л.
--   3) НЕ меняет, если: единица не совпадает, цена отличается от вашей больше чем в 2,5 раза
--      (скорее всего другой продукт или фасовка) или позиция помечена «проверьте» (неясная фасовка).
--   4) Запоминает, какие цены подтверждены накладной — для отчёта по блюдам (файл 37_dish_real_cost.sql).
-- Старые цены не теряются: остаются в истории цен (карточка продукта у руководителя).
-- Внизу — таблица: что обновилось, что нужно проверить и каких продуктов в накладных не было.

create table if not exists invoice_ref(
  key text primary key, title text, unit text, price numeric,
  inc text[], exc text[] default '{}', prio int default 20,
  doc_date date, src text, note text,
  kg_l boolean default false,   -- соусы/масла: кг и л считаем одинаково
  manual boolean default false  -- неясная фасовка или сорт — не применять автоматически
);
alter table invoice_ref enable row level security;
drop policy if exists invoice_ref_boss on invoice_ref;
create policy invoice_ref_boss on invoice_ref for all using (my_role()='boss') with check (my_role()='boss');

-- какие цены продуктов подтверждены документом
create table if not exists price_source(
  product_id int primary key references products(id) on delete cascade,
  price numeric, doc_date date, src text, ref_key text, set_at timestamptz default now()
);
alter table price_source enable row level security;
drop policy if exists price_source_boss on price_source;
create policy price_source_boss on price_source for all using (my_role()='boss') with check (my_role()='boss');

delete from invoice_ref;
